export class AppleMailProfileImporter extends BaseProfileImporter {
  NAME = "AppleMail";
  USE_FILE_PICKER = true;

  SUPPORTED_ITEMS = {
    accounts: false,
    addressBooks: false,
    calendars: false,
    mailMessages: true,
  };

export class OutlookProfileImporter extends BaseProfileImporter {
  NAME = "Outlook";
  USE_FILE_PICKER = false;

  SUPPORTED_ITEMS = {
    accounts: true,
    addressBooks: true,
    calendars: false,
    mailMessages: true,
  };

async startImport() {
  const gleanData = {
    importer: this._importer.NAME,
    types: Object.entries(this._getItemsChecked())
      .filter(entry => entry[1])
      .map(entry => entry[0])
      .join(","),
  };

} else if (this._sourceProfile.name) {
  gleanData.importer += ",profile";
} else {
  gleanData.importer += ",directory";
}
this._importer.onProgress = (current, total) => {
  this.updateProgress(
    this._importingFromZip ? 0.2 + (0.8 * current) / total : current / total
  );
};
try {
  const restartNeeded = await this._importer.startImport(
    this._sourceProfile.dir,
    this._getItemsChecked()
  );
  Glean.mail.import.record({ ...gleanData, result: "succeeded" });
  this.finish(restartNeeded);
} catch (e) {
  this.showError("error-message-failed");
  Glean.mail.import.record({ ...gleanData, result: "failed" });
